Scripts like this and the "Fragment Matcher" have been helpful; use the TOOL TAXONOMY `jq` commands I listed as well: 
```
#!/archw1z/recon --phase=2 --fixed
# The last attempt failed because one file had non‑UTF‑8 bytes.
# Fixed: read with errors='replace' and catch all decode issues.

python3 -c "
import ast, os, hashlib, difflib, re, sys
from pathlib import Path
from collections import defaultdict

base = Path.home() / 'forensic-indexer'
src_dirs = [base, base / 'scripts']

def norm(src: str) -> str:
    lines = []
    for line in src.splitlines():
        stripped = line.strip()
        if stripped.startswith('#') or stripped.startswith('\"\"\"') or stripped == '':
            continue
        lines.append(stripped)
    return ' '.join(lines).replace(' ', '')

FuncInfo = lambda file, name, start, end, raw, norm_hash: {
    'file': file, 'name': name, 'start': start, 'end': end,
    'norm_hash': norm_hash, 'raw_src': raw
}

all_funcs = []
for d in src_dirs:
    for fpath in d.rglob('*.py'):
        if 'whisper.cpp' in str(fpath):
            continue
        try:
            text = fpath.read_text(encoding='utf-8', errors='replace')
        except Exception:
            continue
        try:
            tree = ast.parse(text)
        except SyntaxError:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                start_line = node.lineno
                end_line = node.end_lineno
                raw = ''.join(text.splitlines(keepends=True)[start_line-1:end_line])
                norm_src = norm(raw)
                h = hashlib.md5(norm_src.encode()).hexdigest()[:12]
                all_funcs.append(FuncInfo(str(fpath.relative_to(base)), node.name, start_line, end_line, raw, h))

by_name = defaultdict(list)
by_hash = defaultdict(list)
for f in all_funcs:
    by_name[f['name']].append(f)
    by_hash[f['norm_hash']].append(f)

print('=== 1. EXACT DUPLICATES (identical normalised source) ===')
for h, group in by_hash.items():
    if len(group) > 1:
        print(f'Hash {h}: {len(group)} copies')
        for g in group:
            print(f'   {g[\"file\"]}:{g[\"start\"]}-{g[\"end\"]}')
        print()

names_of_interest = [
    'extract_word_features', 'parse_vtt', 'time_to_ms', 'parse_time_str',
    'get_keywords', 'count_proper_nouns', 'has_numbers', 'assign_global_speakers',
    'link_global_speakers', 'process_file', 'vup_upload'
]
print('=== 2. SIMILARITY MATRIX FOR COMMON DUPLICATED FUNCTIONS ===')
for name in names_of_interest:
    group = by_name[name]
    if len(group) < 2:
        continue
    print(f'--- Function: {name} ({len(group)} implementations) ---')
    files = [g['file'] for g in group]
    sources = [g['raw_src'] for g in group]
    for i in range(len(group)):
        for j in range(i+1, len(group)):
            ratio = difflib.SequenceMatcher(None, sources[i], sources[j]).ratio()
            if ratio < 1.0:
                print(f'  {files[i]:<50} vs {files[j]:<50}  similarity: {ratio:.1%}')
    first = sources[0].strip()[:200].replace('\n', '\\n')
    print(f'  Excerpt (first impl): {first}...')
    print()

print('=== PHASE 2 COMPLETE ===')
"
```
